els tower of london","1516|20|tower of london jewels","1516|20|jewel house tower of london","1516|20|jewel house at the tower of london","1516|20|kohinoor tower of london","1516|20|imperial state crown","1516|20|st edward s crown","1516|20|british crown jewels","1516|21|white tower","1516|21|white tower tower of london","1516|21|white tower london","1516|21|the white tower london","1516|22|ceremony of the keys","1516|22|tower of london ceremony of the keys","1516|22|ceremony of the keys tickets","1516|22|tower of london ceremony of the keys tickets","1516|22|the keys tower of london","1516|23|yeoman warders","1516|23|yeoman warder tower of london","1516|23|tower of london yeoman warder tour","1516|23|tower of london yeoman tour","1516|23|tower of london beefeater tour","1516|23|beefeater tower of london","1516|23|beefeater tour london","1516|23|beefeater yeoman warder","1516|24|tower of london ravens","1516|24|ravenmaster tower of london","1516|25|traitors gate","1516|25|tower of london traitors gate","1516|25|traitors gate london","1516|26|bloody tower","1516|26|bloody tower tower of london","1516|26|bloody tower london","1516|27|tower green london","1516|27|scaffold site tower of london","1516|28|tower of london menagerie","1516|29|tower of london dungeon","1516|30|things to do near tower of london","1516|30|attractions near tower of london","1516|30|what to do near the tower of london","1516|30|what to do near tower of london","1516|30|things to do around tower of london","1516|31|tower of london","1516|31|the tower of london","1516|31|tower of london london","1516|31|tower of london uk","1516|31|tower of london england","1516|31|tower of london london uk","1516|31|tower london uk","1516|31|tower the london"]) x),
hits AS (
  SELECT sq.ce, sq.term, ids.cluster, ids.ord, LENGTH(ids.idn) len
  FROM sq JOIN ids ON sq.ce = ids.ce AND STRPOS(CONCAT(' ', sq.tn, ' '), CONCAT(' ', ids.idn, ' ')) > 0
),
first_hit AS (SELECT ce, term, cluster FROM hits QUALIFY ROW_NUMBER() OVER (PARTITION BY ce, term ORDER BY ord, len DESC) = 1),
long_hit AS (SELECT ce, term, cluster FROM hits QUALIFY ROW_NUMBER() OVER (PARTITION BY ce, term ORDER BY len DESC, ord) = 1),
m AS (
  SELECT sq.*, f.cluster AS cl_first, l.cluster AS cl_long
  FROM sq LEFT JOIN first_hit f USING (ce, term) LEFT JOIN long_hit l USING (ce, term)
),
kwraw AS (
  SELECT cmap.ce, k.ad_group_id, k.ad_group_criterion_keyword_match_type mt, k.ad_group_criterion_keyword_text kt,
    TRIM(REGEXP_REPLACE(REGEXP_REPLACE(NORMALIZE(LOWER(k.ad_group_criterion_keyword_text), NFD), r'\p{M}', ''), r'[^a-z0-9]+', ' ')) AS tn
  FROM `segment-data.google_adwords_prepaid.p_ads_Keyword_6251119615` k JOIN cmap USING (campaign_id)
  WHERE k._PARTITIONTIME = TIMESTAMP('2026-10-27') AND cmap.ce IS NOT NULL AND (cmap.st = 'ENABLED' OR cmap.ce = '176')
    AND NOT k.ad_group_criterion_negative AND k.ad_group_criterion_status = 'ENABLED'
),
kwhit AS (
  SELECT kwraw.ce, kwraw.ad_group_id, kwraw.kt, kwraw.mt, ids.cluster
  FROM kwraw JOIN ids ON kwraw.ce = ids.ce AND STRPOS(CONCAT(' ', kwraw.tn, ' '), CONCAT(' ', ids.idn, ' ')) > 0
  QUALIFY ROW_NUMBER() OVER (PARTITION BY kwraw.ce, kwraw.ad_group_id, kwraw.kt, kwraw.mt ORDER BY ids.ord, LENGTH(ids.idn) DESC) = 1
),
kwall AS (SELECT kwraw.ce, kwraw.ad_group_id, kwraw.kt, kwraw.mt, kwhit.cluster FROM kwraw LEFT JOIN kwhit USING (ce, ad_group_id, kt, mt)),
agshare AS (
  SELECT ce, ad_group_id, cluster, COUNT(*) / SUM(COUNT(*)) OVER (PARTITION BY ce, ad_group_id) sh FROM kwall GROUP BY 1,2,3
),
out AS (
  SELECT 'A_first' sec, ce, cl_first k1, CAST(NULL AS STRING) k2, COUNT(*) n, SUM(clicks) clicks, ROUND(SUM(spend)) spend, ROUND(SUM(conv),1) conv FROM m WHERE clicks > 0 GROUP BY 1,2,3,4
  UNION ALL
  SELECT 'B_long', ce, cl_long, CAST(NULL AS STRING), COUNT(*), SUM(clicks), ROUND(SUM(spend)), ROUND(SUM(conv),1) FROM m WHERE clicks > 0 AND IFNULL(cl_long,'~') != IFNULL(cl_first,'~') GROUP BY 1,2,3,4
  UNION ALL
  SELECT * FROM (SELECT 'C_unm', ce, term, CAST(NULL AS STRING), 1, clicks, ROUND(spend), ROUND(conv,1) FROM m WHERE cl_first IS NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY ce ORDER BY clicks DESC) <= 15)
  UNION ALL
  SELECT * FROM (SELECT 'D_topterm', ce, cl_first, term, 1, clicks, ROUND(spend), ROUND(conv,1) FROM m WHERE cl_first IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY ce, cl_first ORDER BY clicks DESC) = 1)
  UNION ALL
  SELECT 'E_kw', ce, cluster, CAST(NULL AS STRING), COUNT(DISTINCT LOWER(kt)), COUNT(*), CAST(COUNT(DISTINCT ad_group_id) AS FLOAT64), CAST(NULL AS FLOAT64) FROM kwall GROUP BY 1,2,3,4
  UNION ALL
  SELECT 'F_mt', ce, mt, CAST(NULL AS STRING), COUNT(DISTINCT LOWER(kt)), COUNT(*), CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64) FROM kwall GROUP BY 1,2,3,4
  UNION ALL
  SELECT 'G_ded', ce, cluster, CAST(NULL AS STRING), COUNTIF(sh >= 0.5), CAST(NULL AS INT64), CAST(NULL AS FLOAT64), CAST(NULL AS FLOAT64) FROM agshare WHERE cluster IS NOT NULL GROUP BY 1,2,3,4
  UNION ALL
  SELECT 'H_stmt', cmap.ce, s.segments_search_term_match_type, CAST(NULL AS STRING), CAST(NULL AS INT64), SUM(s.metrics_clicks), ROUND(SUM(s.metrics_cost_micros)/1e6), ROUND(SUM(s.metrics_conversions),1)
  FROM `segment-data.google_adwords_prepaid.p_ads_SearchQueryStats_6251119615` s JOIN cmap USING (campaign_id)
  WHERE s._PARTITIONTIME BETWEEN TIMESTAMP('2026-07-30') AND TIMESTAMP('2026-10-27') AND cmap.ce IS NOT NULL GROUP BY 1,2,3,4
)
SELECT * FROM out ORDER BY sec, ce, clicks DESC
